package com.franco.desco.adapter.in.web.inventory;
import com.franco.desco.application.inventory.InventoryCommands;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.inventory.InventoryModels;import org.springframework.stereotype.Component;
@Component public class InventoryWebMapper{
 public InventoryCommands.ListAssets assets(int p,int s,Long empresaId,Long tipoId,String estado){return new InventoryCommands.ListAssets(new PageRequest<>(p,s,new InventoryCommands.AssetFilter(empresaId,tipoId,estado),null,null));}
 public InventoryCommands.ListSupplies supplies(int p,int s){return new InventoryCommands.ListSupplies(new PageRequest<>(p,s,null,null,null));}
 public InventoryResponses.AssetSummary response(InventoryModels.AssetSummary v){return new InventoryResponses.AssetSummary(v.bienInventarioId(),v.empresaId(),v.empresa(),v.tipoBienId(),v.tipoBien(),v.codigoPatrimonial(),v.nombre(),v.marca(),v.modelo(),v.serie(),v.estadoBien(),v.vehiculo(),v.placa(),v.tipoVehiculo(),v.kilometrajeKm());}
 public InventoryResponses.AssetDetail response(InventoryModels.AssetDetail v){return new InventoryResponses.AssetDetail(v.bienInventarioId(),v.empresaId(),v.empresa(),v.tipoBienId(),v.tipoBien(),v.codigoPatrimonial(),v.nombre(),v.marca(),v.modelo(),v.serie(),v.estadoBien(),v.estado(),v.placa(),v.tipoVehiculo(),v.kilometrajeKm(),v.recursos().stream().map(x->new InventoryResponses.Resource(x.recursoProgramadoId(),x.estadoProceso(),x.cantidadProgramada(),x.fechaProgramacion(),x.campaniaVentaId(),x.operativoVentaId(),x.salidaCampoId())).toList(),v.movimientos().stream().map(x->new InventoryResponses.Movement(x.recursoMovimientoId(),x.tipoMovimiento(),x.cantidad(),x.fechaHora(),x.observacion())).toList());}
 public InventoryResponses.Supply response(InventoryModels.Supply v){return new InventoryResponses.Supply(v.suministroId(),v.codigo(),v.nombre(),v.unidadMedida(),v.estado(),v.stock());}
 public InventoryResponses.SupplyMovement response(InventoryModels.SupplyMovement v){return new InventoryResponses.SupplyMovement(v.suministroMovimientoId(),v.suministroId(),v.codigo(),v.nombre(),v.unidadMedida(),v.recursoProgramadoId(),v.tipoMovimiento(),v.cantidad(),v.fechaHora(),v.documentoReferencia(),v.observacion(),v.usuario());}
}
